cat > merge.py <<'EOF'
import json, pandas as pd

FIELD_MAP = {"user_id":"user_id","id":"user_id","userId":"user_id",
             "email":"email","email_address":"email",
             "full_name":"name","name":"name","userName":"name",
             "registration_date":"created_date","created_at":"created_date","joined":"created_date",
             "status":"status"}
ACTIVE_COLS = ("is_active","active")
FIELDS = ["name","email","created_date","status"]

def to_bool(v):
    if isinstance(v,str): return v.strip().lower() in ("true","1","yes","y","t")
    return bool(v)

def norm_date(v):
    if v is None or (isinstance(v,float) and pd.isna(v)) or v == "": return None
    try: return pd.to_datetime(v).strftime("%Y-%m-%d")
    except Exception: return str(v)

def normalize(df):
    recs = []
    for row in df.to_dict(orient="records"):
        r = {}
        for k, v in row.items():
            if k in FIELD_MAP:
                if v is not None and not (isinstance(v,float) and pd.isna(v)):
                    r[FIELD_MAP[k]] = v
            elif k in ACTIVE_COLS and "status" not in r and v is not None and not (isinstance(v,float) and pd.isna(v)):
                r["status"] = "active" if to_bool(v) else "inactive"
        if "user_id" not in r: continue
        r["user_id"] = int(r["user_id"])
        if "created_date" in r: r["created_date"] = norm_date(r["created_date"])
        for f in ("name","email","status"):
            if f in r: r[f] = str(r[f]).strip()
        recs.append(r)
    return recs

sources = {
    "source_a": normalize(pd.DataFrame(json.load(open("/data/source_a/users.json")))),
    "source_b": normalize(pd.read_csv("/data/source_b/users.csv", dtype=str)),
    "source_c": normalize(pd.read_parquet("/data/source_c/users.parquet")),
}
by_user = {}
for s, recs in sources.items():
    for r in recs:
        by_user.setdefault(r["user_id"], {}).setdefault(s, r)  # first occurrence within source

merged, conflicts = [], []
for uid in sorted(by_user):
    per = by_user[uid]
    out = {"user_id": uid}
    for f in FIELDS:
        vals = {s: per[s][f] for s in ("source_a","source_b","source_c") if s in per and per[s].get(f) is not None}
        sel = next(iter(vals.values()), None)
        out[f] = sel
        if len(set(vals.values())) > 1:
            conflicts.append({"user_id": uid, "field": f, "values": vals, "selected": sel})
    merged.append(out)

df = pd.DataFrame(merged, columns=["user_id"]+FIELDS)
df["user_id"] = df["user_id"].astype("int64")
for f in FIELDS: df[f] = df[f].astype("object")
df.to_parquet("/app/merged_users.parquet", index=False)
json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, open("/app/conflicts.json","w"), indent=2)
print(df); print(df.dtypes); print(json.dumps(conflicts, indent=1))
EOF
./envcp merge.py :/app/merge.py && ./envrun 'cd /app && python3 merge.py'
